
/* ===== 全局 ===== */
.folder-ui {
  width: 100%;
  position: relative;
  padding-top: 36px;
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'STSong', 'Microsoft YaHei UI', serif;
  color: #2c2416;
}

/* ===== 顶部标签栏 ===== */
.folder-cover {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  z-index: 2;
}

.cover-head {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding-right: 8px;
}

.cover-tab {
  flex-shrink: 0;
  height: 34px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #fff;
  border: none;
  border-radius: 8px 8px 0 0;
  background: linear-gradient(135deg, #b8864e, #a0713a);
  box-shadow: 0 -1px 0 rgba(255, 255, 255, 0.2) inset;
  pointer-events: none;
  white-space: nowrap;
  user-select: none;
}

.cover-line {
  height: 3px;
  background: linear-gradient(90deg, #b8864e 0%, #d4a76a 50%, #b8864e 100%);
  border-radius: 2px;
  pointer-events: none;
}

/* ===== 角色名标签 ===== */
.name-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 1px;
}

.name-tab {
  border: none;
  border-radius: 6px 6px 0 0;
  background: transparent;
  color: #8a6e4a;
  font-size: 13px;
  font-weight: 700;
  padding: 5px 14px;
  cursor: pointer;
  transform: translateY(1px);
  transition: all 0.2s ease;
  letter-spacing: 0.5px;
  opacity: 0.7;
}

.name-tab:hover {
  opacity: 0.9;
  background: rgba(184, 134, 78, 0.1);
}

.name-tab.active {
  opacity: 1;
  background: linear-gradient(135deg, #b8864e, #a0713a);
  color: #fff;
  box-shadow: 0 2px 6px rgba(120, 80, 30, 0.2);
}

/* ===== 主体卡片 ===== */
.folder-main {
  display: flex;
  align-items: stretch;
  background: linear-gradient(180deg, #fcf6ea, #f5ead2);
  border: 2px solid #b8864e;
  border-radius: 0 14px 14px 14px;
  box-shadow: 0 6px 24px rgba(80, 55, 20, 0.18);
  min-height: 240px;
  overflow: hidden;
}

/* ===== 系统信息侧栏 ===== */
.folder-tab {
  width: min(26%, 180px);
  padding: 14px 0 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: linear-gradient(180deg, rgba(184, 134, 78, 0.08), transparent);
}

.tab-block {
  background: #fff;
  border: 1px solid #d4c4a8;
  border-right: none;
  border-radius: 10px 0 0 10px;
  padding: 8px 12px;
  box-shadow: 0 1px 3px rgba(80, 55, 20, 0.06);
}

.tab-key {
  display: block;
  font-size: 11px;
  color: #9a7b55;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.tab-value {
  display: block;
  margin-top: 2px;
  font-size: 13px;
  font-weight: 700;
  color: #4a3418;
}

/* ===== 内容区 ===== */
.note-board {
  flex: 1;
  background: #fffdf9;
  border-left: 2px solid #d4c4a8;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* 角色名头部 */
.char-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
}

.char-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, #b8864e, #d4a76a);
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(184, 134, 78, 0.3);
}

.char-name {
  font-size: 18px;
  font-weight: 700;
  color: #3d2b12;
  letter-spacing: 1px;
}

.char-divider {
  height: 2px;
  background: linear-gradient(90deg, #d4c4a8, transparent);
  border-radius: 2px;
  margin: 2px 0 8px;
}

/* 好感度条 */
.favor-row {
  margin-bottom: 6px;
}

.favor-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  font-size: 13px;
  color: #5a4425;
}

.favor-label b {
  color: #b0604a;
  font-size: 14px;
}

.favor-track {
  height: 8px;
  width: 100%;
  border-radius: 999px;
  background: #ede3cf;
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(80, 55, 20, 0.1);
}

.favor-fill {
  height: 100%;
  background: linear-gradient(90deg, #e8a09c, #d4736a);
  border-radius: 999px;
  transition: width 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
  box-shadow: 0 0 6px rgba(212, 115, 106, 0.3);
}

/* 信息列表 */
.info-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.info-item {
  display: flex;
  align-items: baseline;
  padding: 6px 10px;
  background: rgba(184, 134, 78, 0.05);
  border-radius: 6px;
  gap: 8px;
}

.info-tag {
  flex-shrink: 0;
  font-size: 12px;
  font-weight: 700;
  color: #9a7b55;
  min-width: 3em;
  letter-spacing: 0.5px;
}

.info-val {
  font-size: 14px;
  color: #3d2b12;
  line-height: 1.6;
  word-break: break-all;
}

/* ===== 手机适配 ===== */
@media (max-width: 767px) {
  .folder-ui {
    padding-top: 30px;
  }

  .cover-head {
    display: flex;
    align-items: flex-end;
    gap: 6px;
    padding-right: 4px;
    flex-wrap: nowrap;
  }

  .cover-tab {
    height: 28px;
    font-size: 11px;
    padding: 0 10px;
    letter-spacing: 0.5px;
    border-radius: 6px 6px 0 0;
  }

  .name-tabs {
    flex: 1;
    min-width: 0;
    overflow-x: auto;
    flex-wrap: nowrap;
    gap: 4px;
    scrollbar-width: none;
    padding-bottom: 2px;
  }
  .name-tabs::-webkit-scrollbar {
    display: none;
  }
  .name-tab {
    flex-shrink: 0;
    font-size: 12px;
    padding: 5px 10px;
    white-space: nowrap;
    border-radius: 5px 5px 0 0;
  }

  .folder-main {
    flex-direction: column;
    border-radius: 0 12px 12px 12px;
    min-height: 180px;
  }

  .folder-tab {
    width: 100%;
    padding: 10px 12px 0;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
    background: transparent;
  }

  .tab-block {
    flex: 1;
    min-width: 0;
    border: 1px solid #d4c4a8;
    border-radius: 8px;
    padding: 6px 10px;
    box-shadow: 0 1px 3px rgba(80, 55, 20, 0.06);
  }

  .tab-key {
    font-size: 10px;
  }
  .tab-value {
    font-size: 12px;
  }

  .note-board {
    border-left: none;
    border-top: 2px solid #d4c4a8;
    padding: 14px;
  }

  .char-avatar {
    width: 30px;
    height: 30px;
    font-size: 14px;
  }
  .char-name {
    font-size: 16px;
  }

  .favor-track {
    height: 6px;
  }
  .favor-label {
    font-size: 12px;
  }
  .favor-label b {
    font-size: 13px;
  }
}

@media (max-width: 420px) {
  .folder-ui {
    padding-top: 26px;
  }

  .cover-tab {
    height: 24px;
    font-size: 10px;
    padding: 0 7px;
    border-radius: 5px 5px 0 0;
  }

  .name-tab {
    font-size: 11px;
    padding: 4px 7px;
    border-radius: 4px 4px 0 0;
  }

  .folder-tab {
    padding: 8px 10px 0;
    gap: 4px;
  }
  .tab-block {
    padding: 4px 8px;
  }

  .note-board {
    padding: 10px;
    gap: 8px;
  }

  .char-avatar {
    width: 26px;
    height: 26px;
    font-size: 12px;
  }
  .char-name {
    font-size: 14px;
  }

  .info-item {
    padding: 5px 8px;
  }
  .info-tag {
    font-size: 11px;
  }
  .info-val {
    font-size: 13px;
  }
}
